import sysimport osimport jsonimport socketimport base64import loggingfrom datetime import datetimefrom PyQt6.QtCore import Qt, QThread, pyqtSignalfrom PyQt6.QtGui import QPixmapfrom PyQt6.QtWidgets import (    QApplication, QMainWindow, QWidget, QVBoxLayout, QHBoxLayout,    QLineEdit, QTextEdit, QPushButton, QListWidget, QLabel, QInputDialog,    QMessageBox, QFileDialog)LOGS_DIR = "logs"if not os.path.exists(LOGS_DIR):    os.makedirs(LOGS_DIR)log_filename = datetime.now().strftime("client_%Y-%m-%d_%H-%M-%S.log")log_filepath = os.path.join(LOGS_DIR, log_filename)logging.basicConfig(    level=logging.INFO,    format="%(asctime)s [%(levelname)s] %(message)s",    handlers=[        logging.FileHandler(log_filepath, encoding="utf-8"),        logging.StreamHandler(sys.stdout)    ])logging.info("==================================================")logging.info("🚀 CLIENTE D-TECH MESSENGER INICIADO")logging.info("==================================================")MSN_STYLE = """    QMainWindow { background-color: #ECE9D8; }    QWidget { font-family: 'Segoe UI', 'Tahoma', sans-serif; font-size: 11px; }    #Header {        background: qlineargradient(x1:0, y1:0, x2:1, y2:0, stop:0 #0058EE, stop:1 #3A93FE);        color: white; font-weight: bold; font-size: 13px; padding: 6px;        border-bottom: 2px solid #003B9E;    }    QTextEdit, QListWidget, QLineEdit {        background-color: #FFFFFF; border: 2px inset #7F9DB9; border-radius: 2px;    }    QPushButton {        background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #FFFFFF, stop:0.5 #ECE9D8, stop:1 #D6D2C2);        border: 1px solid #003C74; border-radius: 3px; padding: 4px 8px; font-weight: bold;    }    QPushButton:hover {        background: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 #FFEFA9, stop:1 #FFC73D);    }"""class NetworkWorker(QThread):    raw_received = pyqtSignal(str)    def __init__(self, sock):        super().__init__()        self.sock = sock    def run(self):        logging.info("Hilo de escucha de red (NetworkWorker) iniciado.")        while True:            try:                data = self.sock.recv(65536).decode('utf-8')                if data:                    self.raw_received.emit(data)                else:                    logging.warning("Conexión perdida con el servidor.")                    break            except Exception as e:                logging.error(f"Error en NetworkWorker: {e}")                breakclass DTechMessenger(QMainWindow):    def __init__(self):        super().__init__()        logging.info("Inicializando ventana principal de D-TECH Messenger...")        self.setWindowTitle("D-TECH Messenger")        self.resize(720, 520)        self.setStyleSheet(MSN_STYLE)        self.contacts_file = "contacts.json"        self.sock = None        self.account_data = None        self.chat_histories = {}        self.active_chat = None        if not os.path.exists("downloads"):            os.makedirs("downloads")        if not self.authenticate_or_register():            sys.exit()        self.init_ui()        self.connect_to_server()    def format_dtech_email(self, text):        text = text.strip().lower()        if not text.endswith("@d-tech.gob.eus"):            username = text.split("@")[0]            return f"{username}@d-tech.gob.eus"        return text    def authenticate_or_register(self):        if os.path.exists(self.contacts_file):            try:                with open(self.contacts_file, "r", encoding="utf-8") as f:                    self.account_data = json.load(f)                saved_user = self.account_data.get("user_account", "")                saved_oup = self.account_data.get("oup", "")                password_input, ok = QInputDialog.getText(                    self, "Login D-TECH", f"Cuenta: {saved_user}\nContraseña (OUP):",                    QLineEdit.EchoMode.Password                )                if ok and f"{password_input.strip()}.oup" == saved_oup:                    return True                else:                    QMessageBox.critical(self, "Error", "Contraseña incorrecta.")                    return False            except Exception as e:                QMessageBox.critical(self, "Error", f"Error cargando cuenta: {e}")                return False        else:            username, ok1 = QInputDialog.getText(self, "Registro D-TECH", "Apodo/Nombre de usuario:")            if not ok1 or not username.strip(): return False            password, ok2 = QInputDialog.getText(self, "Registro D-TECH", "Contraseña (OUP):", QLineEdit.EchoMode.Password)            if not ok2 or not password.strip(): return False            full_account = self.format_dtech_email(username)            self.account_data = {                "user_account": full_account,                "oup": f"{password.strip()}.oup",                "contacts": ["Notas (Espacio Personal)"]            }            self.save_contacts_file()            return True    def save_contacts_file(self):        with open(self.contacts_file, "w", encoding="utf-8") as f:            json.dump(self.account_data, f, indent=4)    def init_ui(self):        central_widget = QWidget()        self.setCentralWidget(central_widget)        main_layout = QVBoxLayout(central_widget)        self.header_label = QLabel(f"🟢 {self.account_data['user_account']}")        self.header_label.setObjectName("Header")        main_layout.addWidget(self.header_label)        body_layout = QHBoxLayout()        # CHAT IZQUIERDA        chat_layout = QVBoxLayout()        self.chat_title = QLabel("<i>Selecciona un contacto o grupo para chatear</i>")        chat_layout.addWidget(self.chat_title)        self.chat_display = QTextEdit()        self.chat_display.setReadOnly(True)        chat_layout.addWidget(self.chat_display)        input_layout = QHBoxLayout()        self.msg_input = QLineEdit()        self.msg_input.returnPressed.connect(self.send_message)        input_layout.addWidget(self.msg_input)        btn_attach = QPushButton("📎 Adjuntar")        btn_attach.clicked.connect(self.attach_file)        input_layout.addWidget(btn_attach)        btn_send = QPushButton("Enviar")        btn_send.clicked.connect(self.send_message)        input_layout.addWidget(btn_send)        chat_layout.addLayout(input_layout)        body_layout.addLayout(chat_layout, 2)        # CONTACTOS DERECHA        contacts_layout = QVBoxLayout()        contacts_layout.addWidget(QLabel("<b>Contactos / Grupos</b>"))        self.contacts_list_widget = QListWidget()        self.contacts_list_widget.itemClicked.connect(self.select_chat)        self.refresh_contacts_ui()        contacts_layout.addWidget(self.contacts_list_widget)        btn_add = QPushButton("➕ Agregar Contacto")        btn_add.clicked.connect(self.add_contact_dialog)        contacts_layout.addWidget(btn_add)        btn_group = QPushButton("👥 Crear Grupo")        btn_group.clicked.connect(self.create_group_dialog)        contacts_layout.addWidget(btn_group)        # NUEVO BOTÓN: Añadir a grupo existente        btn_add_to_group = QPushButton("➕ Añadir a Grupo")        btn_add_to_group.clicked.connect(self.add_members_to_group_dialog)        contacts_layout.addWidget(btn_add_to_group)        body_layout.addLayout(contacts_layout, 1)        main_layout.addLayout(body_layout)    def refresh_contacts_ui(self):        self.contacts_list_widget.clear()        for contact in self.account_data["contacts"]:            self.contacts_list_widget.addItem(contact)            if contact not in self.chat_histories:                self.chat_histories[contact] = ""    def select_chat(self, item):        self.active_chat = item.text()        logging.info(f"Chat activo seleccionado: {self.active_chat}")        self.chat_title.setText(f"<b>Conversación: {self.active_chat}</b>")        self.chat_display.setHtml(self.chat_histories.get(self.active_chat, ""))    def add_contact_dialog(self):        name, ok = QInputDialog.getText(self, "Agregar Contacto", "Nombre de usuario o correo D-TECH:")        if ok and name.strip():            formatted = self.format_dtech_email(name)            if formatted == self.account_data["user_account"]:                QMessageBox.warning(self, "Aviso", "No puedes agregarte a ti mismo.")                return            if self.sock:                self.sock.send(f"CHECK_EXIST:{formatted}".encode('utf-8'))    def create_group_dialog(self):        g_name, ok1 = QInputDialog.getText(self, "Nuevo Grupo", "Nombre del grupo:")        if not ok1 or not g_name.strip(): return        members_raw, ok2 = QInputDialog.getText(self, "Miembros del Grupo", "Escribe los correos separados por coma:")        if ok2 and members_raw.strip():            group_tag = f"👥 [Grupo] {g_name.strip()}"            if self.sock:                payload = f"CREATE_GROUP:{group_tag}|{members_raw.strip()}"                self.sock.send(payload.encode('utf-8'))    # NUEVA FUNCIÓN: Añadir miembros a un grupo ya seleccionado    def add_members_to_group_dialog(self):        if not self.active_chat or not self.active_chat.startswith("👥"):            QMessageBox.warning(self, "Aviso", "Selecciona primero un Grupo de la lista para añadirle integrantes.")            return        new_members, ok = QInputDialog.getText(            self,             "Añadir Miembros al Grupo",             f"Escribe los correos a añadir a '{self.active_chat}' (separados por coma):"        )        if ok and new_members.strip() and self.sock:            payload = f"ADD_TO_GROUP:{self.active_chat}|{new_members.strip()}"            self.sock.send(payload.encode('utf-8'))    def attach_file(self):        if not self.active_chat:            QMessageBox.warning(self, "Aviso", "Selecciona una conversación activa.")            return        # -------------------------------------------------------------        # CORRECCIÓN: Si es Notas, guardarlo solo localmente sin red        # -------------------------------------------------------------        if "Notas" in self.active_chat:            filepath, _ = QFileDialog.getOpenFileName(self, "Seleccionar archivo para Notas", "", "Todos los archivos (*.*)")            if filepath:                filename = os.path.basename(filepath)                with open(filepath, "rb") as f:                    file_bytes = f.read()                is_img = filename.lower().endswith(('.png', '.jpg', '.jpeg', '.gif'))                if is_img:                    entry = f"<b>[Nota - Imagen]:</b><br><img src='data:image/png;base64,{base64.b64encode(file_bytes).decode()}' width='150'><br>"                else:                    entry = f"<b>[Nota - Archivo]:</b> 📄 {filename}<br>"                self.chat_histories[self.active_chat] += entry                self.chat_display.append(entry)                logging.info("Archivo guardado localmente en Notas Personal.")            return        # -------------------------------------------------------------        filepath, _ = QFileDialog.getOpenFileName(self, "Seleccionar archivo para enviar", "", "Todos los archivos (*.*)")        if filepath and self.sock:            # ... (el resto del código de attach_file sigue igual)            filename = os.path.basename(filepath)                        with open(filepath, "rb") as f:                file_bytes = f.read()            hex_data = file_bytes.hex()            payload = f"FILE|{self.active_chat}|{filename}|{hex_data}"            self.sock.send(payload.encode('utf-8'))            is_img = filename.lower().endswith(('.png', '.jpg', '.jpeg', '.gif'))            if is_img:                entry = f"<b>Tú mandaste una imagen:</b><br><img src='data:image/png;base64,{base64.b64encode(file_bytes).decode()}' width='150'><br>"            else:                entry = f"<b>Tú adjuntaste un archivo:</b> 📄 {filename}<br>"            self.chat_histories[self.active_chat] += entry            self.chat_display.append(entry)    def connect_to_server(self):        ip_server, ok_ip = QInputDialog.getText(            self, "Conexión al Servidor", "Introduce la dirección IP del servidor:",            QLineEdit.EchoMode.Normal, "127.0.0.1"        )        if not ok_ip or not ip_server.strip():            ip_server = "127.0.0.1"        else:            ip_server = ip_server.strip()        port_server, ok_port = QInputDialog.getInt(            self, "Puerto del Servidor", "Introduce el puerto de conexión:", 5000, 1, 65535        )        if not ok_port:            port_server = 5000        try:            logging.info(f"Intentando conectar al servidor {ip_server}:{port_server}...")            self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)            self.sock.connect((ip_server, port_server))                        msg = self.sock.recv(1024).decode('utf-8')            if msg == 'LOGIN_REQ':                self.sock.send(self.account_data["user_account"].encode('utf-8'))            self.worker = NetworkWorker(self.sock)            self.worker.raw_received.connect(self.process_incoming_data)            self.worker.start()            self.setWindowTitle(f"D-TECH Messenger - Conectado a {ip_server}:{port_server}")        except Exception as e:            logging.critical(f"No se pudo conectar al servidor: {e}")            self.chat_display.setText(f"<font color='red'><b>Error de conexión:</b> {e}</font>")    def process_incoming_data(self, raw_data):        logging.info(f"TRAMA RECIBIDA: {raw_data[:80]}...")        if raw_data.startswith("CHECK_RESULT|"):            _, status, contact = raw_data.split("|", 2)            if status == "EXISTS":                if contact not in self.account_data["contacts"]:                    self.account_data["contacts"].append(contact)                    self.save_contacts_file()                    self.refresh_contacts_ui()                    QMessageBox.information(self, "Éxito", f"Contacto {contact} añadido.")            else:                QMessageBox.warning(self, "Error", f"La cuenta {contact} NO existe.")            return        if raw_data.startswith("GROUP_CREATED|"):            _, g_name = raw_data.split("|", 1)            if g_name not in self.account_data["contacts"]:                self.account_data["contacts"].append(g_name)                self.save_contacts_file()                self.refresh_contacts_ui()            return        if raw_data.startswith("INCOMING_FILE|"):            _, sender, target, filename, hex_data = raw_data.split("|", 4)            file_bytes = bytes.fromhex(hex_data)                        out_path = os.path.join("downloads", filename)            with open(out_path, "wb") as f:                f.write(file_bytes)            is_img = filename.lower().endswith(('.png', '.jpg', '.jpeg', '.gif'))            b64_img = base64.b64encode(file_bytes).decode()            chat_target = target if target.startswith("👥") else sender            QMessageBox.warning(                self, "⚠️ Advertencia de Seguridad D-TECH",                f"Has recibido el archivo '{filename}' de {sender}."            )            if is_img:                entry = f"<b>{sender}:</b><br><img src='data:image/png;base64,{b64_img}' width='150'><br>"            else:                entry = f"<b>{sender} adjuntó:</b> 📄 {filename} <i>(Guardado en /downloads)</i><br>"            if chat_target not in self.chat_histories:                self.chat_histories[chat_target] = ""            self.chat_histories[chat_target] += entry            if self.active_chat == chat_target:                self.chat_display.append(entry)            return        if raw_data.startswith("GROUP_MSG|"):            _, sender, group_name, msg = raw_data.split("|", 3)            entry = f"<b>{sender} [{group_name}]:</b> {msg}<br>"            if group_name not in self.chat_histories:                self.chat_histories[group_name] = ""            self.chat_histories[group_name] += entry            if self.active_chat == group_name:                self.chat_display.append(entry)            return        if raw_data.startswith("REMOVE_CONTACT|"):            contact = raw_data.split("|", 1)[1]            if contact in self.account_data["contacts"]:                self.account_data["contacts"].remove(contact)                self.save_contacts_file()                self.refresh_contacts_ui()            return        if raw_data.startswith("SYSTEM|"):            _, target, text = raw_data.split("|", 2)            sys_msg = f"<i><font color='gray'>[Sistema]: {text}</font></i><br>"            if target not in self.chat_histories:                self.chat_histories[target] = ""            self.chat_histories[target] += sys_msg            if self.active_chat == target:                self.chat_display.append(sys_msg)            return        if "|" in raw_data:            sender, msg = raw_data.split("|", 1)            formatted_msg = f"<b>{sender}:</b> {msg}<br>"            if sender not in self.chat_histories:                self.chat_histories[sender] = ""            self.chat_histories[sender] += formatted_msg            if self.active_chat == sender:                self.chat_display.append(f"<b>{sender}:</b> {msg}")    def send_message(self):        text = self.msg_input.text().strip()        if not text or not self.active_chat:            return        if "Notas" in self.active_chat:            note_entry = f"<b>[Nota]:</b> {text}<br>"            self.chat_histories[self.active_chat] += note_entry            self.chat_display.append(f"<b>[Nota]:</b> {text}")            self.msg_input.clear()            return        if not self.sock:            self.chat_display.append("<font color='red'>No estás conectado al servidor.</font>")            return        payload = f"{self.active_chat}|{text}"        try:            self.sock.send(payload.encode('utf-8'))            my_entry = f"<b>Tú:</b> {text}<br>"            self.chat_histories[self.active_chat] += my_entry            self.chat_display.append(f"<b>Tú:</b> {text}")            self.msg_input.clear()        except Exception as e:            self.chat_display.append(f"<font color='red'>Error al enviar: {e}</font>")if __name__ == "__main__":    app = QApplication(sys.argv)    window = DTechMessenger()    window.show()    sys.exit(app.exec())